import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"部署本地模型","description":"電腦部署 Ollama／LM Studio／A1111／ComfyUI，手機 MiniTavern 經區域網 BYOK 連線；本地大模型與生圖教學入口。","frontmatter":{"title":"部署本地模型","description":"電腦部署 Ollama／LM Studio／A1111／ComfyUI，手機 MiniTavern 經區域網 BYOK 連線；本地大模型與生圖教學入口。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"部署本地模型 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"電腦部署 Ollama／LM Studio／A1111／ComfyUI，手機 MiniTavern 經區域網 BYOK 連線；本地大模型與生圖教學入口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/local"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/local"}]]},"headers":[],"relativePath":"zh-TW/local/index.md","filePath":"zh-TW/local/index.md","lastUpdated":1787224147000}'),o={name:"zh-TW/local/index.md"};function l(i,t,n,h,c,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="部署本地模型" tabindex="-1">部署本地模型 <a class="header-anchor" href="#部署本地模型" aria-label="Permalink to &quot;部署本地模型&quot;">​</a></h1><p>MiniTavern 是 <strong>BYOK（自備金鑰）</strong> 客戶端：請求發往你設定的位址，不強制綁定某一家雲廠商。<br> 「部署本地模型」指在<strong>自己的電腦</strong>上跑推理服務，再用手機上的 MiniTavern 透過區域網連線。</p><p>本欄目分兩條線：</p><table tabindex="0"><thead><tr><th>類型</th><th>用途</th><th>入口</th></tr></thead><tbody><tr><td><strong>語言模型部署</strong></td><td>聊天、續寫、轉寫生圖 prompt</td><td><a href="/ultra_guides/zh-TW/quickstart">30 分鐘通關</a> · <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a></td></tr><tr><td><strong>生圖模型部署</strong></td><td><code>/imagine</code>、附件生圖、背景圖</td><td><a href="/ultra_guides/zh-TW/local/image-gen/">生圖概覽</a></td></tr></tbody></table><p>沒有 GPU、也不想裝服務時，可先用 <a href="/ultra_guides/zh-TW/free-cloud/">免費雲端</a> 拿試用／免費額度。</p><blockquote><p>MiniTavern <strong>本身不在手機上跑大模型或擴散模型</strong>。服務跑在電腦上，App 只負責角色卡、世界書、聊天與生圖請求。</p></blockquote><h2 id="語言模型部署" tabindex="-1">語言模型部署 <a class="header-anchor" href="#語言模型部署" aria-label="Permalink to &quot;語言模型部署&quot;">​</a></h2><p>在電腦上運行大語言模型（Ollama、LM Studio、KoboldCPP 等），App 裡填 <strong>自訂 (OpenAI)</strong>。</p><table tabindex="0"><thead><tr><th>項目</th><th>建議</th></tr></thead><tbody><tr><td>電腦</td><td>Windows／macOS／Linux；記憶體建議 <strong>16GB+</strong></td></tr><tr><td>顯示卡（可選）</td><td>NVIDIA／Apple Silicon 更快；純 CPU 也能跑</td></tr><tr><td>網路</td><td>手機與電腦同一 Wi‑Fi（勿用訪客隔離網）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>工具</th><th>適合誰</th><th>預設連接埠</th></tr></thead><tbody><tr><td><a href="/ultra_guides/zh-TW/ollama/install">Ollama</a></td><td>命令列省事、一鍵拉模型</td><td><code>11434</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/lmstudio/install">LM Studio</a></td><td>圖形介面、點選下載</td><td><code>1234</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/koboldcpp/install">KoboldCPP</a></td><td>角色扮演社群常用</td><td><code>5001</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/llamacpp/install">llama.cpp</a></td><td>直接跑 GGUF</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/localai/install">LocalAI</a></td><td>Docker／一站式相容層</td><td><code>8080</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/jan/install">Jan</a> · <a href="/ultra_guides/zh-TW/textgen/install">text-generation-webui</a></td><td>其它圖形或外掛生態</td><td>見各頁</td></tr></tbody></table><p>推薦順序：<a href="/ultra_guides/zh-TW/quickstart">30 分鐘通關</a> → <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a> → <a href="/ultra_guides/zh-TW/local/models">推薦模型</a> → <a href="/ultra_guides/zh-TW/connect-app/minitavern">在 MiniTavern 中設定</a> → 卡住查 <a href="/ultra_guides/zh-TW/troubleshoot">排錯</a>。</p><h2 id="生圖模型部署" tabindex="-1">生圖模型部署 <a class="header-anchor" href="#生圖模型部署" aria-label="Permalink to &quot;生圖模型部署&quot;">​</a></h2><p>在電腦上跑 Stable Diffusion 系服務，App <strong>設定 → 生圖 → 生圖連線</strong> 選 A1111 或 ComfyUI。</p><table tabindex="0"><thead><tr><th>後端</th><th>預設連接埠</th><th>教學</th></tr></thead><tbody><tr><td><a href="/ultra_guides/zh-TW/local/image-gen/a1111">A1111／SD WebUI</a></td><td><code>7860</code></td><td>需 <code>--api --listen</code></td></tr><tr><td><a href="/ultra_guides/zh-TW/local/image-gen/comfyui">ComfyUI</a></td><td><code>8188</code>（Desktop 常見 <code>8000</code>）</td><td>需 <code>--listen</code></td></tr></tbody></table><p>總覽與硬體說明見 <a href="/ultra_guides/zh-TW/local/image-gen/">生圖模型部署</a>；填連線見 <a href="/ultra_guides/zh-TW/local/image-gen/connect-app">連 App</a>。</p><h2 id="重要提醒" tabindex="-1">重要提醒 <a class="header-anchor" href="#重要提醒" aria-label="Permalink to &quot;重要提醒&quot;">​</a></h2><ul><li>手機裡填的位址必須是電腦的 <strong>區域網 IP</strong>，<strong>不要</strong>填 <code>localhost</code>／<code>127.0.0.1</code>。</li><li>語言模型 Base URL 通常以 <code>/v1</code> 結尾（如 <code>http://192.168.1.8:11434/v1</code>）。</li><li>生圖 A1111 必須開 <code>--api</code>；ComfyUI 必須能區域網存取。</li><li>防火牆放行對應連接埠；勿把未鑑權 API 暴露到公網。</li></ul>',17)])])}const g=a(o,[["render",l]]);export{p as __pageData,g as default};
